    K.fine(() => { V._cb(K, KX + 4.2, 0.94, KZ + 1.2, 1.6, 1.3, 1.2, 0.14, P.b, 'steel'); K.seg([KX + 3.6, 1.9, KZ + 1.0], [KX + KR * 0.85, KY - 0.4, KZ + KR * 0.5], 0.22, P.t, 'metal', { seg: 8 }); K.light(KX + 5.02, 1.7, KZ + 1.2, 0.16, C.PL, 2.4);
      for (let i = 0; i < 3; i++) { const a = 2.2 + i * 0.5; K.cyl(KX + Math.cos(a) * 3.95, 0.94, KZ + Math.sin(a) * 3.95, 0.16, 0.2, 1.3, '#B7B0A0', 'stone', { seg: 6 }); } });
