    for (let i = 0; i < R.length - 1; i++) for (let j = 0; j < n; j++) { const j2 = (j + 1) % n; if (o.open && j2 === 0) continue; V(R[i][j]); V(R[i + 1][j]); V(R[i][j2]); V(R[i][j2]); V(R[i + 1][j]); V(R[i + 1][j2]); }
    if (o.cap0) { const c = cen(R[0]); for (let j = 0; j < n; j++) { V(c); V(R[0][j]); V(R[0][(j + 1) % n]); } }
    if (o.cap1) { const t = R[R.length - 1], c = cen(t); for (let j = 0; j < n; j++) { V(c); V(t[(j + 1) % n]); V(t[j]); } }
