    const Pt = (r, y, j) => { const a = rot + j / n * PI * 2; return [cx + Math.cos(a) * r * kx, y, cz + Math.sin(a) * r * kz]; }, G0 = o.g0 ? new T.Color(o.g0) : null, G1 = o.g1 ? new T.Color(o.g1) : null; /* o.g0/o.g1: degradê de cor de baixo para cima (a cor da peça multiplica) */
