    for (let i = 0; i < prof.length - 1; i++) { const [r0, ya] = prof[i], [r1, yb] = prof[i + 1]; for (let j = 0; j < n; j++) { const a = Pt(r0, ya, j), b = Pt(r0, ya, j + 1), c = Pt(r1, yb, j), d = Pt(r1, yb, j + 1); if (r0 > 1e-6) { V(a); V(c); V(b); } if (r1 > 1e-6) { V(b); V(c); V(d); } } }
