  _line(K, pts, w, h, col, mat, o) { const B = BR.erevane; for (let i = 0; i < pts.length - 1; i++) B._bar(K, pts[i], pts[i + 1], w, h, col, mat, o); if (o && o.loop) B._bar(K, pts[pts.length - 1], pts[0], w, h, col, mat, o); }, /* polilinha de vigas (fios e frisos) */
