  _lens(K, P, x, y, z, r) { K.cyl(x, y - 0.18, z, r * 0.72, r * 0.55, 0.18, P.c, null, { e: 2.4, seg: 8 }); K.cyl(x, y, z, r, r * 0.8, 0.32, P.d, 'dark', { seg: 8, facet: true }); K.fine(() => K.cyl(x, y + 0.08, z, r * 1.1, r * 1.1, 0.08, P.t, 'metal', { seg: 8, facet: true })); }, /* lente antigravidade (teal) sob peça que paira */
