  /* 4.3f: bulbo (K.bulb) que na versão leve também perde anéis do perfil (ficam o primeiro, o último e um sim outro não) */
  _bulbo(K, prof, x, y, z, col, mat, o) { return K.bulb(K.lite && prof.length > 4 ? prof.filter((p, i) => i === 0 || i === prof.length - 1 || i % 2 === 1) : prof, x, y, z, col, mat, o); },
  /* 4.3f: escudos hexagonais de osso sobre o domo MB (U.tessara._escudos); na versão leve placas maiores (menos peças, mesma cobertura) e sem os enfeites f */
