    const C0 = new T.Color(o.c0 || '#4C4033'), C1 = new T.Color(o.c1 || '#5E4F3D'), CB = new T.Color(o.cb || '#7D6E58'), M0 = new T.Color(o.musgo || '#506537'), M1 = new T.Color('#6A803F'), tmp = new T.Color(), pos = [], col = [], idx = [];
    const put = (x, y, z, t) => { tmp.copy(C0).lerp(C1, smooth01(0.0, 0.7, t)); const m = smooth01(0.5, 0.7, ms(x, z)) * (o.k == null ? 0.85 : o.k) * (1 - smooth01(0.75, 1.0, t)); if (m > 0) tmp.lerp(M0, m).lerp(M1, m * smooth01(0.6, 0.85, ms(z, x))); tmp.lerp(CB, smooth01(0.72, 1.0, t) * 0.85); pos.push(x, y, z); col.push(tmp.r, tmp.g, tmp.b); };
