    for (const t of [0.22, 0.5]) { const rr = r * (t < 0.3 ? 1.03 : 1.06) + 0.12; U.tessara._cano(K, Array.from({ length: 9 }, (_, i) => { const a = i / 8 * PI * 2; return [x + Math.cos(a) * rr, y0 + h * t, z + Math.sin(a) * rr]; }), 0.16, P.b, 'bone', { n: 4, k: 1.5 }); }
    if (o.slit !== false) { K.sph(x + ux * r * 0.98, y0 + h * 0.4, z + uz * r * 0.98, 1, '#2A211B', 'wet', { sx: 0.34, sy: h * 0.19, sz: r * 0.36, ry: -b, seg: 10 }); K.sph(x + ux * r * 1.07, y0 + h * 0.4, z + uz * r * 1.07, 1, P.am, null, { e: 2.2, sx: 0.16, sy: h * 0.16, sz: r * 0.2, ry: -b, seg: 8 }); }
