    for (const [a, y, L] of [[0.9, 4.6, 3.2], [3.6, 6.4, 2.6], [5.3, 3.2, 2.4]]) K.piece([Math.cos(a) * 1.6, y, Math.sin(a) * 1.6], () => { const c = Math.cos(a), sn = Math.sin(a); K.trunk([[c * 1.2, y, sn * 1.2, 0.42], [c * (1.2 + L * 0.5), y + L * 0.45, sn * (1.2 + L * 0.5), 0.26], [c * (1.2 + L), y + L * 0.62, sn * (1.2 + L), 0]], '#FFFFFF', 'bone', { n: 6, c0: P.b, c1: '#EDE4CC' }); Y._foto(K, P, c * (1.2 + L * 0.5), y + L * 0.45 + 0.42, sn * (1.2 + L * 0.5), 0.13);
      K.fine(() => X._lente(K, [c * (1.2 + L * 0.3), y + L * 0.3, sn * (1.2 + L * 0.3)], a + 0.8, 0.5, -0.8, 1.6, 0.7, 'leaf', { f: 'folha', c0: '#2F6A3A', c1: LF, nu: 4, nv: 2 })); });
    K.piece([0.9, 6.2, -1.4], () => K.anim({ t: 'sway', p: [0.9, 7.6, -1.4], amp: 0.1, speed: 1.4 }, () => X._lente(K, [0.9, 7.6, -1.45], -1.1, -1.35, 0.3, 3.2, 1.5, 'skin', { c0: tc, c1: X._tom(tc, 0.55), cup: 0.08, nu: 5, nv: 2, t: 0.1, cb: 0.8 })));
