    for (let i = 0; i < 3; i++) Y._espinho(K, P, [0.5 - i * 0.9, 2.85 - i * 0.05, 0], [0.0 - i * 0.9, 3.7 - i * 0.1, 0], 0.15);
    for (const s of [-1, 1]) { K.trunk([[-1.6, 2.2, s * 0.9, 0.42], [-2.7, 2.9, s * 1.35, 0.28], [-3.5, 3.7, s * 1.5, 0.1], [-3.7, 4.1, s * 1.45, 0]], '#FFFFFF', 'bone', { n: 7, c0: P.b, c1: '#EDE4CC' }); Y._foto(K, P, 2.05, 1.85, s * 0.72, 0.13); Y._foto(K, P, 1.7, 2.1, s * 1.05, 0.1); X._lanterna(K, -0.6, 0.55, s * 2.0, [[0, 0], [0.62, 0.25], [0.8, 0.8], [0.62, 1.35], [0, 1.55]], 10, 1.5);
      Y._cano(K, [[-0.3, 1.0, s * 1.9], [0.9, 1.15, s * 1.25], [1.9, 1.05, s * 0.55]], 0.11, P.t, 'skin', { n: 4, k: 2 }); }
    K.sph(2.2, 1.55, 0, 1, P.g, 'glass', { sx: 0.32, sy: 0.32, sz: 0.66, rz: -0.5, seg: 10 }); K.sph(2.2, 0.85, 0, 1, P.d, 'skin', { sx: 0.8, sy: 0.7, sz: 0.85, seg: 10 });
    K.anim({ t: 'sway', p: [1.9, 0.6, 0], amp: 0.06, speed: 2.4 }, () => { K.trunk([[1.9, 0.6, 0, 0.45], [2.9, 0.45, 0, 0.36], [3.6, 0.6, 0, 0.12]], P.d, 'skin', { n: 6 }); for (const s of [-1, 1]) Y._espinho(K, P, [3.0, 0.5, s * 0.3], [3.5, 0.95, s * 0.35], 0.07); });
