    /* raízes-garra (peças soltas) */
    for (let k = 0; k < 5; k++) { const a = (k + 0.5) / 5 * PI * 2, c = Math.cos(a), s = Math.sin(a); K.piece([c * 7.0, 0, s * 7.0], () => { V._ov(K, [c * 3.0, 3.2, s * 3.0], [c * 6.0, 4.0, s * 6.0], 1.1, P.a, 'chitin', { seg: 10 }); K.sph(c * 6.0, 4.0, s * 6.0, 0.85, P.b, 'chitin', { seg: 8 }); V._ov(K, [c * 6.0, 4.0, s * 6.0], [c * 7.9, -0.2, s * 7.9], 0.78, P.b, 'chitin', { seg: 9 });
      V._pico(K, P, [c * 7.7, 0.6, s * 7.7], [c * 8.9, -0.3, s * 8.9], 0.4, { n: 4 }); V._pico(K, P, [c * 6.0, 4.6, s * 6.0], [c * 6.6, 6.6, s * 6.6], 0.3, { n: 4 }); }); }
    /* placas do talo na cor do time */
    for (let k = 0; k < 6; k++) { const a = k / 6 * PI * 2 + PI / 6; B._escama(K, P, 2.75, a, 8.8, 1.36, 2.7, 0.5, 1.15, k % 2 ? P.b : tc, { meia: true, seg: 10 }); }
