    K.anim({ t: 'recoil', dist: 1.1 }, () => { K.trunk([[1.8, BY, 0, 0.62], [3.4, BY + 0.05, 0, 0.6], [5.0, BY + 0.09, 0, 0.53], [6.6, BY + 0.12, 0, 0.47]], '#FFFFFF', 'bone', { n: 12, c0: '#6A3A36', c1: '#E8DCC8' });
      for (const f of K.lite ? [0.7] : [0.45, 0.72]) { const x = 1.8 + 4.8 * f; K.cyl(x - 0.15, BY + 0.12 * f, 0, 0.66 - 0.12 * f, 0.66 - 0.12 * f, 0.3, P.d, 'chitin', { rz: -H, seg: 10 }); }
      K.cyl(6.4, BY + 0.12, 0, 0.74, 0.52, 0.7, P.m, 'wet', { rz: -H, seg: 12 }); K.sph(7.05, BY + 0.12, 0, 0.36, P.ac, null, { e: 2.2, seg: 8 });
      K.fine(() => { for (const x of [3.0, 4.2, 5.4]) U.vorag._esp(K, P, [x, BY + 0.45, 0], [x - 0.4, BY + 1.05, 0], 0.09); }); });
