    /* couraça com esporões */
    for (let i = 0; i < 10; i++) { const a = (i + 0.5) / 10 * PI * 2, c = Math.cos(a), s = Math.sin(a); B._escama(K, P, 10.6, a, 2.9, 1.18, 2.9, 0.9, 2.1, i % 2 ? P.a : '#4A2030', { meia: true, seg: 12 }); V._pico(K, P, [c * 11.1, 4.2, s * 11.1], [c * 13.4, 6.6, s * 13.4], 0.45, { n: 5 }); }
    for (let g = 0; g < 3; g++) { const am = g / 3 * PI * 2 + PI / 6; K.piece([Math.cos(am) * 8, 8, Math.sin(am) * 8], () => { for (const a of [am - PI / 6, am + PI / 6]) B._escama(K, P, 7.9, a, 8.6, 0.92, 3.1, 0.7, 1.75, tc, { meia: true, seg: 12 }); }); }
    /* pernas-pilar (peças soltas) */
