      TP([[0.95, s * 2.8], [0.05, s * 3.95], [-0.75, s * 4.15], [-1.25, s * 2.8]], 1.46, 0.03, tc, 'paint', { b: 0.02 });
      const fx = -0.35, fz = s * 1.95;
