    for (const s of S2) K.anim({ t: 'sway', p: [5.15, 1.5, s * 0.36], amp: 0.2, speed: 6, ph: s > 0 ? 0 : PI }, () => K.seg([5.15, 1.5, s * 0.36], [5.75, 1.1, s * 0.28], 0.1, P.bo, 'bone', { taper: 0.2, seg: 5 }));
