      K.trunk([[0, y0, 0.03, 0.08], [mid[0], mid[1], mid[2], 0.06], [tip[0], tip[1], tip[2], 0.02]], '#FFFFFF', 'bark', { n: 5, c0: T1, c1: '#6A7484', bark: 0.2, seed: seed + i }); K.patina(FR, 0.8, 0.2, seed + i);
